SELECT COALESCE(SUM(payments.amount), 0) AS total,
       COUNT(*) AS paidSessionCount
FROM payments
INNER JOIN sales_sessions ON sales_sessions.id = payments.sales_session_id
WHERE sales_sessions.store_id = #{storeId}
  AND payments.status = 'PAID'
  AND payments.confirmed_at >= #{from}
  AND payments.confirmed_at < #{to}

SELECT AVG(TIMESTAMPDIFF(SECOND, orders.created_at, order_items.served_at) / 60.0)
           AS averageWaitMinutes
FROM order_items
INNER JOIN orders ON orders.id = order_items.order_id
INNER JOIN sales_sessions ON sales_sessions.id = orders.sales_session_id
WHERE sales_sessions.store_id = #{storeId}
  AND orders.created_at >= #{from}
  AND orders.created_at < #{to}
  AND order_items.served_at IS NOT NULL

SELECT COALESCE(SUM(bill_discounts.discount_amount), 0) AS totalDiscountAmount,
       COUNT(*) AS discountedSessionCount
FROM bill_discounts
INNER JOIN payments ON payments.id = bill_discounts.payment_id
WHERE bill_discounts.store_id = #{storeId}
  AND payments.status = 'PAID'
  AND payments.confirmed_at >= #{from}
  AND payments.confirmed_at < #{to}
